class Solution {
public:
    int maxBuilding(int n, vector<vector<int>>& restrictions) {
        restrictions.push_back({1, 0});
        restrictions.push_back({n, n - 1});
        sort(restrictions.begin(), restrictions.end());

        vector<vector<int>> r;
        for (const auto& item : restrictions) {
            if (!r.empty() && r.back()[0] == item[0]) {
                r.back()[1] = min(r.back()[1], item[1]);
            } else {
                r.push_back(item);
            }
        }
        int m = r.size();

        for (int i = 1; i < m; ++i) {
            r[i][1] = min(r[i][1], r[i - 1][1] + (r[i][0] - r[i - 1][0]));
        }
        for (int i = m - 2; i >= 0; --i) {
            r[i][1] = min(r[i][1], r[i + 1][1] + (r[i + 1][0] - r[i][0]));
        }

        int ans = 0;
        for (int i = 0; i < m - 1; ++i) {
            int peak = (r[i][1] + r[i + 1][1] + (r[i + 1][0] - r[i][0])) / 2;
            ans = max(ans, peak);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxBuilding(int n, int[][] restrictions) {
        List<int[]> list = new ArrayList<>();
        list.add(new int[]{1, 0});
        list.add(new int[]{n, n - 1});
        for (int[] rest : restrictions) list.add(new int[]{rest[0], rest[1]});
        list.sort((a, b) -> Integer.compare(a[0], b[0]));

        List<int[]> r = new ArrayList<>();
        for (int[] item : list) {
            if (!r.isEmpty() && r.get(r.size() - 1)[0] == item[0]) {
                r.get(r.size() - 1)[1] = Math.min(r.get(r.size() - 1)[1], item[1]);
            } else {
                r.add(item);
            }
        }
        int m = r.size();

        for (int i = 1; i < m; ++i) {
            r.get(i)[1] = Math.min(r.get(i)[1], r.get(i - 1)[1] + (r.get(i)[0] - r.get(i - 1)[0]));
        }
        for (int i = m - 2; i >= 0; --i) {
            r.get(i)[1] = Math.min(r.get(i)[1], r.get(i + 1)[1] + (r.get(i + 1)[0] - r.get(i)[0]));
        }

        int ans = 0;
        for (int i = 0; i < m - 1; ++i) {
            int peak = (r.get(i)[1] + r.get(i + 1)[1] + (r.get(i + 1)[0] - r.get(i)[0])) / 2;
            ans = Math.max(ans, peak);
        }
        return ans;
    }
}

