var maxBuilding = function(n, restrictions) {
    const list = [...restrictions, [1, 0], [n, n - 1]];
    list.sort((a, b) => a[0] - b[0]);

    const r = [];
    for (const [id, h] of list) {
        if (r.length > 0 && r[r.length - 1][0] === id) {
            r[r.length - 1][1] = Math.min(r[r.length - 1][1], h);
        } else {
            r.push([id, h]);
        }
    }
    const m = r.length;

    for (let i = 1; i < m; ++i) {
        r[i][1] = Math.min(r[i][1], r[i - 1][1] + (r[i][0] - r[i - 1][0]));
    }
    for (let i = m - 2; i >= 0; --i) {
        r[i][1] = Math.min(r[i][1], r[i + 1][1] + (r[i + 1][0] - r[i][0]));
    }

    let ans = 0;
    for (let i = 0; i < m - 1; ++i) {
        const peak = Math.floor((r[i][1] + r[i + 1][1] + (r[i + 1][0] - r[i][0])) / 2);
        ans = Math.max(ans, peak);
    }
    return ans;
};
